class TestKyberKeyPair:
    """Validate key pair structure and serialization."""

    def test_initialization(self):
        """KeyPair must initialize with empty bytes."""
        kp = KyberKeyPair()
        assert kp.public_key == b""
        assert kp.secret_key == b""

    def test_initialization_with_keys(self):
        """KeyPair must accept pre-populated keys."""
        pub = b"\x01" * KYBER_PUBLICKEYBYTES
        sec = b"\x02" * KYBER_SECRETKEYBYTES
        kp = KyberKeyPair(pub, sec)
        assert kp.public_key == pub
        assert kp.secret_key == sec

    def test_public_key_length_validation(self):
        """Public key must match KYBER_PUBLICKEYBYTES."""
        with pytest.raises(ValueError):
            KyberKeyPair(b"short", b"\x00" * KYBER_SECRETKEYBYTES)

    def test_secret_key_length_validation(self):
        """Secret key must match KYBER_SECRETKEYBYTES."""
        with pytest.raises(ValueError):
            KyberKeyPair(b"\x00" * KYBER_PUBLICKEYBYTES, b"short")

    def test_serialization_roundtrip(self):
        """Serialization must preserve key data."""
        pub = os.urandom(KYBER_PUBLICKEYBYTES)
        sec = os.urandom(KYBER_SECRETKEYBYTES)
        kp = KyberKeyPair(pub, sec)
        serialized = kp.serialize()
        deserialized = KyberKeyPair.deserialize(serialized)
        assert deserialized.public_key == pub
        assert deserialized.secret_key == sec

    def test_serialization_format(self):
        """Serialization must use length-prefixed format."""
        pub = os.urandom(KYBER_PUBLICKEYBYTES)
        sec = os.urandom(KYBER_SECRETKEYBYTES)
        kp = KyberKeyPair(pub, sec)
        serialized = kp.serialize()
        # Format: [pub_len:4][pub][sec_len:4][sec]
        pub_len = struct.unpack(">I", serialized[:4])[0]
        assert pub_len == KYBER_PUBLICKEYBYTES
        sec_len = struct.unpack(">I", serialized[4 + KYBER_PUBLICKEYBYTES:8 + KYBER_PUBLICKEYBYTES])[0]
        assert sec_len == KYBER_SECRETKEYBYTES

    def test_deserialize_invalid_length(self):
        """Deserialization must reject malformed data."""
        with pytest.raises(ValueError):
            KyberKeyPair.deserialize(b"\x00\x00\x00\x05short")


