class TestRoundTrip:
    """Validate end-to-end encryption/decryption flow."""

    def test_full_roundtrip(self, interface, mock_lib):
        """Must successfully encrypt and decrypt a message."""
        # Mock the C library to simulate actual Kyber operations
        def mock_enc(ct_buf, ss_buf, pub_buf, msg_buf):
            # Simulate encryption: copy message to ciphertext buffer
            msg = ctypes.string_at(msg_buf, KYBER_INDCPA_MSGBYTES)
            ct = msg + b"\x00" * (KYBER_CIPHERTEXTBYTES - len(msg))
            ctypes.memmove(ct_buf, ct, len(ct))
            # Generate deterministic shared secret
            ss = b"\x42" * KYBER_SSBYTES
            ctypes.memmove(ss_buf, ss, len(ss))
            return KyberError.SUCCESS

        def mock_dec(ss_buf, sec_buf, ct_buf):
            # Simulate decryption: extract message from ciphertext
            ct = ctypes.string_at(ct_buf, KYBER_CIPHERTEXTBYTES)
            msg = ct[:KYBER_INDCPA_MSGBYTES]
            ss = b"\x42" * KYBER_SSBYTES
            ctypes.memmove(ss_buf, ss, len(ss))
            return KyberError.SUCCESS

        mock_lib.kyber_enc.side_effect = mock_enc
        mock_lib.kyber_dec.side_effect = mock_dec

        # Generate keypair
        mock_lib.kyber_keypair.return_value = KyberError.SUCCESS
        kp = interface.generate_keypair()

        # Encrypt
        msg = b"Hello, Kyber!"
        ct, ss_enc = interface.encrypt(kp.public_key, msg)

        # Decrypt
        ss_dec = interface.decrypt(kp.secret_key, ct)

        # Verify shared secrets match
        assert ss_enc == ss_dec


