class TestSecurity:
    """Validate security-critical properties."""

    def test_no_key_material_in_logs(self, interface, mock_lib, caplog):
        """Key material must not appear in logs."""
        import logging
        with caplog.at_level(logging.DEBUG):
            mock_lib.kyber_keypair.return_value = KyberError.SUCCESS
            kp = interface.generate_keypair()
            # Check no key material in logs
            for record in caplog.records:
                assert kp.public_key not in record.message.encode()
                assert kp.secret_key not in record.message.encode()

    def test_shared_secret_isolation(self, interface, mock_lib):
        """Different messages must produce different shared secrets."""
        mock_lib.kyber_enc.return_value = KyberError.SUCCESS
        pub = os.urandom(KYBER_PUBLICKEYBYTES)
        msg1 = os.urandom(KYBER_INDCPA_MSGBYTES)
        msg2 = os.urandom(KYBER_INDCPA_MSGBYTES)
        _, ss1 = interface.encrypt(pub, msg1)
        _, ss2 = interface.encrypt(pub, msg2)
        assert ss1 != ss2

    def test_ciphertext_entropy(self, interface, mock_lib):
        """Ciphertext must have high entropy."""
        mock_lib.kyber_enc.return_value = KyberError.SUCCESS
        pub = os.urandom(KYBER_PUBLICKEYBYTES)
        msg = os.urandom(KYBER_INDCPA_MSGBYTES)
        ct, _ = interface.encrypt(pub, msg)
        # Check byte distribution
        byte_counts = [ct.count(i) for i in range(256)]
        assert max(byte_counts) < len(ct) * 0.1  # No byte dominates

    def test_keypair_uniqueness(self, interface, mock_lib):
        """Generated keypairs must be unique."""
        mock_lib.kyber_keypair.return_value = KyberError.SUCCESS
        keypairs = [interface.generate_keypair() for _ in range(10)]
        public_keys = [kp.public_key for kp in keypairs]
        secret_keys = [kp.secret_key for kp in keypairs]
        assert len(set(public_keys)) == 10
        assert len(set(secret_keys)) == 10


